   431  void SetVoiceStack(espeak_VOICE *v, const char *variant_name)
   432  {
   433          SSML_STACK *sp;
   434          sp = &ssml_stack[0];
   435
   436          if (v == NULL) {
   437                  memset(sp, 0, sizeof(ssml_stack[0]));
   438                  return;
   439          }
   440          if (v->languages != NULL)
   441                  strcpy(sp->language, v->languages);
   442          if (v->name != NULL)
   443                  strncpy0(sp->voice_name, v->name, sizeof(sp->voice_name));
   444          sp->voice_variant_number = v->variant;
   445          sp->voice_age = v->age;
   446          sp->voice_gender = v->gender;
   447
   448          if (variant_name[0] == '!' && variant_name[1] == 'v' && variant_name[2] == PATHSEP)
   449                  variant_name += 3; // strip variant directory name, !v plus PATHSEP
   450          strncpy0(base_voice_variant_name, variant_name, sizeof(base_voice_variant_name));
   451          memcpy(&base_voice, &current_voice_selected, sizeof(base_voice));
   452  }
