   462  int ReadClause(Translator *tr, char *buf, short *charix, int *charix_top, int n_buf, int *tone_type, char *voice_change)
   463  {
   464          /* Find the end of the current clause.
   465              Write the clause into  buf
   466
   467              returns: clause type (bits 0-7: pause x10mS, bits 8-11 intonation type)
   468
   469              Also checks for blank line (paragraph) as end-of-clause indicator.
   470
   471              Does not end clause for:
   472                  punctuation immediately followed by alphanumeric  eg.  1.23  !Speak  :path
   473                  repeated punctuation, eg.   ...   !!!
   474           */
   475
   476          int c1 = ' '; // current character
   477          int c2; // next character
   478          int cprev = ' '; // previous character
   479          int cprev2 = ' ';
   480          int c_next;
   481          int parag;
   482          int ix = 0;
   483          int j;
   484          int nl_count;
   485          int linelength = 0;
   486          int phoneme_mode = 0;
   487          int n_xml_buf;
   488          int terminator;
   489          bool any_alnum = false;
   490          int punct_data = 0;
   491          bool is_end_clause;
   492          int announced_punctuation = 0;
   493          bool stressed_word = false;
   494          int end_clause_after_tag = 0;
   495          int end_clause_index = 0;
   496          wchar_t xml_buf[N_XML_BUF+1];
   497
   498          #define N_XML_BUF2 20
   499          char xml_buf2[N_XML_BUF2+2]; // for &<name> and &<number> sequences
   500          static char ungot_string[N_XML_BUF2+4];
   501          static int ungot_string_ix = -1;
   502
   503          if (clear_skipping_text) {
   504                  skipping_text = false;
   505                  clear_skipping_text = false;
   506          }
   507
   508          tr->phonemes_repeat_count = 0;
   509          tr->clause_upper_count = 0;
   510          tr->clause_lower_count = 0;
   511          *tone_type = 0;
   512
   513          if (ungot_char2 != 0)
   514                  c2 = ungot_char2;
   515          else
   516                  c2 = GetC();
   517
   518          while (!Eof() || (ungot_char != 0) || (ungot_char2 != 0) || (ungot_string_ix >= 0)) {
   519                  if (!iswalnum(c1)) {
   520                          if ((end_character_position > 0) && (count_characters > end_character_position)) {
   950                          // try to break at a word boundary (unless we actually reach the end of buffer).
   951                          // (n_buf-4) is to allow for 3 bytes of multibyte character plus terminator.
   952                          buf[ix] = ' ';
   953                          buf[ix+1] = 0;
   954                          UngetC(c2);
   955                          return CLAUSE_NONE;
   956                  }
   957          }
   958
   959          if (stressed_word)
   960                  ix += utf8_out(CHAR_EMPHASIS, &buf[ix]);
   961          if (end_clause_after_tag)
   962                  RemoveChar(&buf[end_clause_index]); // delete clause-end punctiation
   963          buf[ix] = ' ';
   964          buf[ix+1] = 0;
   965          return CLAUSE_EOF; // end of file
   966  }
